        QVERIFY2(!r.value("isError").toBool(), qPrintable(text(r)));
        r = tool("montage_place_media", QJsonObject{{"project", project}, {"media", ball}, {"at", 20.08}, {"in", 0}, {"out", 0.4}, {"mode", "ripple_overwrite"}});
        QVERIFY2(!r.value("isError").toBool(), qPrintable(text(r)));
